import { createRbac, defineRoles } from '../src/index.js';
import { memoryStore } from '../src/stores/memory.js';

const roles = defineRoles({
  viewer: ['invoice:read'],
  admin: { inherits: ['viewer'], permissions: ['invoice:*', 'user:*'] },
});
const rbac = createRbac({ roles, store: memoryStore() });

await rbac.assign('user_1', 'admin', { tenantId: 'acme' });
console.log(await rbac.can({ id: 'user_1' }, 'user:delete', { tenantId: 'acme' })); // true
console.log(await rbac.can({ id: 'user_1' }, 'user:delete', { tenantId: 'globex' })); // false
